public class AllFontsProbe {
    public static void main(String[] args) throws Exception {
        for (FontLoader.Family family : FontLoader.Family.values()) {
            FigletFont font = FontLoader.load(family);
            boolean stray = false;
            boolean trailing = false;
            for (char c = 32; c <= 126; c++) {
                for (String row : font.render(String.valueOf(c))) {
                    if (row.indexOf('@') >= 0) stray = true;
                    if (!row.equals(row.stripTrailing())) trailing = true;
                }
            }
            System.out.println(family + " strayAt=" + stray + " trailingBlank=" + trailing);
        }
    }
}
